function loadState(){try{const saved=JSON.parse(localStorage.getItem(STORE)||'{}');return {...defaultState,...saved,tasks:Array.isArray(saved.tasks)?saved.tasks:[],favorites:Array.isArray(saved.favorites)?saved.favorites:[],seen:Array.isArray(saved.seen)?saved.seen:[],goals:Array.isArray(saved.goals)?saved.goals:[],learningDone:Array.isArray(saved.learningDone)?saved.learningDone:[],wellnessLog:saved.wellnessLog&&typeof saved.wellnessLog==='object'?saved.wellnessLog:{},reflection:saved.reflection&&typeof saved.reflection==='object'?saved.reflection:{good:'',learn:'',next:''}}}catch{return {...defaultState,tasks:[],favorites:[],seen:[],goals:[],learningDone:[],wellnessLog:{},reflection:{good:'',learn:'',next:''}}}}
function save(){try{localStorage.setItem(STORE,JSON.stringify(state));return true}catch{notify('No se pudo guardar. Revisá el espacio disponible del navegador.');return false}}
function notify(msg){toast.textContent=msg;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),2600)}
function escapeHTML(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
