function renderGoals(){const root=document.querySelector('#goal-list');if(!root)return;root.innerHTML=(state.goals||[]).length?state.goals.map((g,i)=>`<div class="goal-item ${g.done?'goal-done':''}"><label><input type="checkbox" data-goal-toggle="${i}" ${g.done?'checked':''}><span>${escapeHTML(g.text)}</span></label><button data-goal-delete="${i}" aria-label="Eliminar prioridad">×</button></div>`).join(''):'<div class="empty-state">Todavía no hay prioridades. Agregá una que te importe.</div>'}
let focusTimer=null,focusRemaining=1500,focusTotal=1500;
function paintFocus(){const el=document.querySelector('#focus-clock');if(el)el.textContent=String(Math.floor(focusRemaining/60)).padStart(2,'0')+':'+String(focusRemaining%60).padStart(2,'0')}
function setupFocus(){clearInterval(focusTimer);focusTimer=null;focusRemaining=focusTotal=1500;paintFocus()}
function stopFocus(){clearInterval(focusTimer);focusTimer=null}
function startFocus(){if(focusTimer)return;focusTimer=setInterval(()=>{focusRemaining--;paintFocus();if(focusRemaining<=0){stopFocus();state.focusSessions=(state.focusSessions||0)+1;state.points+=10;save();const c=document.querySelector('#focus-count');if(c)c.textContent='Sesiones completadas: '+state.focusSessions;const l=document.querySelector('#focus-label');if(l)l.textContent='¡SESIÓN COMPLETADA!';notify('¡Buen trabajo! Sumaste 10 puntos NEXO.');}},1000);notify('Modo enfoque activado. ¡A tu ritmo!')}
function saveNotes(){state.notes=document.querySelector('#agenda-notes')?.value||'';if(save()){const status=document.querySelector('#notes-status');if(status)status.textContent='Guardado · '+new Date().toLocaleTimeString('es-AR',{hour:'2-digit',minute:'2-digit'});notify('Notas guardadas en este navegador.')}}
function saveReflection(){state.reflection={good:document.querySelector('#reflect-good')?.value||'',learn:document.querySelector('#reflect-learn')?.value||'',next:document.querySelector('#reflect-next')?.value||''};save();notify('Balance guardado en este navegador.')}


function wellbeingHomeDate(){const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function wellbeingHomeOrdinal(key){const p=key.split('-').map(Number);return Math.floor(Date.UTC(p[0],p[1]-1,p[2])/86400000)}
function readWellbeingHome(){const today=wellbeingHomeDate();try{const saved=JSON.parse(localStorage.getItem(WELLBEING_HOME_KEY)||'{}');if(saved.date!==today)return {date:today,water:0};return {date:today,water:Math.max(0,Math.min(8,Number(saved.water)||0))}}catch{return {date:today,water:0}}}
function renderWellbeingWater(){const state=readWellbeingHome(),count=document.querySelector('#home-water-count'),label=document.querySelector('#home-water-label');document.querySelectorAll('[data-water-level]').forEach(button=>{const level=Number(button.dataset.waterLevel),filled=level<=state.water;button.classList.toggle('is-filled',filled);button.setAttribute('aria-pressed',String(filled));button.setAttribute('aria-label',(filled?'Vaso registrado '+level:'Registrar hasta '+level+' vasos'))});if(count)count.textContent=state.water;if(label)label.textContent=state.water===0?'Tocá un vaso para registrar agua.':state.water===8?'¡Listo! Registraste los 8 vasos de este contador.':state.water+' de 8 registrados · adaptalo a tus necesidades.'}
function renderWellbeingTip(){const root=document.querySelector('#home-mind-content');if(!root||!wellbeingHomeTips.length)return;const today=wellbeingHomeDate(),index=wellbeingHomeOrdinal(today)%wellbeingHomeTips.length,tip=wellbeingHomeTips[index];wellbeingHomeTipDay=today;const tag=document.querySelector('#home-mind-type');if(tag)tag.textContent=tip.type==='Receta en 3 pasos'?'RECETA RÁPIDA · 3 PASOS':'TIP DE SALUD DEL DÍA';root.innerHTML='<h3 class="home-wellbeing-tip-title">'+escapeHTML(tip.title)+'</h3>'+(Array.isArray(tip.steps)?'<ol class="home-tip-steps">'+tip.steps.map(step=>'<li>'+escapeHTML(step)+'</li>').join('')+'</ol>':'<p class="home-wellbeing-tip-body">'+escapeHTML(tip.body||'Un pequeño recordatorio para cuidarte a tu manera.')+'</p>');const footer=document.querySelector('#home-mind-footer');if(footer)footer.textContent='IDEA '+String(index+1).padStart(2,'0')+' / '+wellbeingHomeTips.length+' · CAMBIA CADA 24 H'}
function setupWellbeingHome(){const root=document.querySelector('#wellbeing-home');if(!root)return;renderWellbeingWater();root.querySelectorAll('[data-water-level]').forEach(button=>button.addEventListener('click',()=>{const level=Number(button.dataset.waterLevel),current=readWellbeingHome();current.water=level<=current.water?level-1:Math.min(8,current.water+1);try{localStorage.setItem(WELLBEING_HOME_KEY,JSON.stringify(current))}catch{notify('No se pudo guardar el contador en este navegador.')}renderWellbeingWater()}));const reset=root.querySelector('[data-water-reset]');reset?.addEventListener('click',()=>{const current={date:wellbeingHomeDate(),water:0};try{localStorage.setItem(WELLBEING_HOME_KEY,JSON.stringify(current))}catch{}renderWellbeingWater();notify('Contador de agua reiniciado.')});if(!wellbeingHomeTips.length){fetch('./wellbeing-tips.json').then(response=>{if(!response.ok)throw new Error('No se pudo cargar el archivo de consejos');return response.json()}).then(tips=>{if(!Array.isArray(tips)||!tips.length)throw new Error('Archivo de consejos vacío');wellbeingHomeTips=tips;renderWellbeingTip()}).catch(()=>{wellbeingHomeTips=[{type:'Tip',title:'Hacé una pausa amable',body:'Tomate un momento para revisar qué necesitás ahora: agua, descanso, movimiento suave o simplemente seguir a tu ritmo.'}];renderWellbeingTip()})}else renderWellbeingTip();if(wellbeingHomeTimer)clearInterval(wellbeingHomeTimer);wellbeingHomeTimer=setInterval(()=>{if(wellbeingHomeTipDay!==wellbeingHomeDate())renderWellbeingTip();const current=readWellbeingHome();if(current.date!==document.querySelector('#home-water-label')?.dataset.date){renderWellbeingWater();const label=document.querySelector('#home-water-label');if(label)label.dataset.date=current.date}},60000);const label=document.querySelector('#home-water-label');if(label)label.dataset.date=wellbeingHomeDate()}

function renderHome(){viewRoot.innerHTML=HOME_HTML;document.querySelector('#daily-text').textContent=prompts[Math.floor(Math.random()*prompts.length)];updateStats();setupWellbeingHome()}
function renderCreate(){viewRoot.innerHTML='<section class="page-content"><div class="content-heading"><div><p class="eyebrow">MUNDO 01 / TALLER CREATIVO</p><h2>Una idea, mil versiones.</h2><p>Diseñá memes con plantillas populares, mové los textos a tu gusto y descargá tu creación.</p></div></div><div class="meme-studio-layout"><article class="tool-panel meme-editor-panel"><div class="meme-studio-heading"><div><p class="section-label">01 / ESTUDIO DE CREACIÓN VIRAL</p><h3>Tu próximo meme empieza acá.</h3></div><span class="meme-live-pill"><span></span> Editor en vivo</span></div><div class="meme-canvas-wrap"><canvas id="meme-canvas" class="meme-preview" width="700" height="700" aria-label="Vista previa de meme. Arrastrá el texto superior o inferior para moverlo."></canvas><div class="meme-canvas-hint"><span>↕</span> Arrastrá los textos sobre la imagen</div></div><div class="form-grid meme-controls"><label class="field">Texto superior<input id="meme-top" maxlength="100" value="YO CUANDO"></label><label class="field">Texto inferior<input id="meme-bottom" maxlength="100" value="POR FIN ES VIERNES"></label><label class="field">Color del texto<input id="meme-color" type="color" value="#ffffff"></label><label class="field">Tamaño del texto <span id="meme-size-label">42 px</span><input id="meme-size" type="range" min="22" max="58" value="42"></label></div><div class="button-row meme-primary-actions"><button class="btn btn-dark" data-action="download-meme">Descargar PNG ↗</button><button class="btn btn-quiet" data-action="random-meme">Cambiar fondo</button><button class="btn btn-outline" data-action="surprise-meme">✦ Sorpréndeme</button></div><p id="meme-status" class="meme-status" role="status">Cargando plantillas populares…</p></article><aside class="tool-panel meme-library-panel"><div class="meme-library-title"><div><p class="section-label">02 / BIBLIOTECA DE FONDOS</p><h3>Encontrá tu plantilla</h3></div><span class="meme-library-count" id="meme-result-count">En tendencia</span></div><form id="meme-search-form" class="meme-search-form"><label class="meme-search-box"><span aria-hidden="true">⌕</span><input id="meme-search" type="search" maxlength="70" placeholder="Buscar Drake, gato, distracted…" autocomplete="off" aria-label="Buscar plantillas de memes"></label><button class="btn btn-dark" type="submit">Buscar</button></form><div class="meme-search-tags"><button type="button" data-meme-query="cat">Gatos</button><button type="button" data-meme-query="drake">Drake</button><button type="button" data-meme-query="dog">Perros</button><button type="button" data-meme-query="success">Éxito</button></div><div id="meme-template-results" class="meme-template-grid"><div class="empty-state">Conectando con la biblioteca de memes…</div></div><p class="meme-library-footnote">Plantillas populares de Imgflip. Los resultados dependen del catálogo disponible en la API.</p></aside></div><div class="world-grid meme-extras-grid" style="grid-template-columns:repeat(auto-fit,minmax(260px,1fr));margin-top:18px"><article class="tool-panel"><p class="section-label">03 / FÁBRICA DE IDEAS</p><h3 style="font:800 23px Manrope">No pienses tanto.</h3><p class="muted" style="line-height:1.7">Un clic y tenés una frase nueva para empezar algo.</p><div class="result-box" id="idea-result">Tu próxima idea te está esperando.</div><div class="button-row"><button class="btn btn-dark" data-action="generate-idea">Generar idea ✳</button><button class="btn btn-quiet" data-action="copy-idea">Copiar texto</button></div></article><article class="tool-panel"><p class="section-label">04 / PERSONAJE IMPROBABLE</p><h3 style="font:800 23px Manrope">Inventá alguien imposible.</h3><div class="result-box" id="character-result">Nombre, habilidad y defecto: todo listo para una historia.</div><button class="btn btn-outline" style="margin-top:13px" data-action="generate-character">Inventar personaje ↗</button></article></div></section>';setupMeme()}
const memeColors=['#edb89b','#b6c9a2','#a9b9df','#e4cf8e','#c9b2dc'];
let memeBg=0,memeImage=null,memeTemplates=[],memeDrag=null,memeTopPos={x:.5,y:.15},memeBottomPos={x:.5,y:.86},memeSearchTerm='';
const memeJokes=[['YO: HOY ME ACUESTO TEMPRANO','TAMBIÉN YO A LAS 3:17 AM'],['ABRO EL APUNTE','EL APUNTE ME ABRE 47 PESTAÑAS MENTALES'],['YO CUANDO DIGO “CINCO MINUTITOS”','DOS HORAS DESPUÉS…'],['MI CEREBRO EN EL EXAMEN','CARGANDO… 1%'],['CUANDO POR FIN ENTIENDO','Y CAMBIAN EL EJERCICIO'],['YO: TODO BAJO CONTROL','EL UNIVERSO: ¿SEGURO?'],['ENTRO A BUSCAR UNA COSA','SALGO CON 18 DATOS INÚTILES'],['HOY SÍ ME ORGANIZO','MI AGENDA: QUÉ MIEDO'],['CUANDO EL WIFI SE TRABA','REPLANTEANDO TODA MI EXISTENCIA'],['DIJE “ES FÁCIL”','FAMOSAS ÚLTIMAS PALABRAS'],['MI PLAN PERFECTO','DEPENDÍA DE QUE TODO SALIERA PERFECTO'],['YO DESPUÉS DE UNA TAREA','NECESITO UN DESCANSO DE MI DESCANSO'],['CUANDO ME RESPONDEN “OK”','INICIA EL ANÁLISIS FORENSE'],['YO RECORDANDO ALGO DE 2017','A LAS 2 DE LA MAÑANA, CLARO'],['ABRO LA CÁMARA FRONTAL SIN QUERER','NUEVO JEFE FINAL DESBLOQUEADO']];
function memeStatus(message){const el=document.querySelector('#meme-status');if(el)el.textContent=message}
function loadMemeTemplates(){if(memeTemplates.length){renderMemeResults();return Promise.resolve(memeTemplates)}return fetch('https://api.imgflip.com/get_memes?type=image').then(r=>{if(!r.ok)throw new Error('HTTP '+r.status);return r.json()}).then(data=>{if(!data.success||!data.data||!Array.isArray(data.data.memes))throw new Error('Respuesta no válida');memeTemplates=data.data.memes.filter(m=>m.url&&m.name&&!/(nsfw|porn|nude|sexual|drug|weed|cocaine|gun|weapon|suicide|self.?harm)/i.test(m.name));renderMemeResults();memeStatus('Listo: '+memeTemplates.length+' plantillas populares disponibles.');return memeTemplates}).catch(()=>{renderMemeResults();memeStatus('No se pudo conectar con Imgflip. Podés seguir usando el fondo gráfico y volver a intentar.');return []})}
function renderMemeResults(){const root=document.querySelector('#meme-template-results');if(!root)return;const q=(document.querySelector('#meme-search')?.value||memeSearchTerm||'').trim().toLowerCase();memeSearchTerm=q;const aliases={'gato':'cat','gatos':'cat','perro':'dog','perros':'dog','éxito':'success','exito':'success','distracción':'distracted','distraccion':'distracted','novio':'boyfriend','novia':'boyfriend','cerebro':'brain','estudiante':'student','trabajo':'work','feliz':'happy','triste':'sad','bebé':'baby','bebe':'baby'};const normalized=aliases[q]||q;const list=(normalized?memeTemplates.filter(m=>m.name.toLowerCase().includes(normalized)):memeTemplates).slice(0,12);const count=document.querySelector('#meme-result-count');if(count)count.textContent=q?(list.length+' resultados'):'Populares';if(!list.length){root.innerHTML='<div class="empty-state meme-empty">No encontramos una plantilla con ese nombre. Probá otra palabra o tocá «Sorpréndeme».</div>';return}root.innerHTML=list.map((m,i)=>'<button type="button" class="meme-template-card '+(memeImage&&memeImage.src===m.url?'selected':'')+'" data-meme-url="'+escapeHTML(m.url)+'" data-meme-name="'+escapeHTML(m.name)+'" aria-label="Usar plantilla '+escapeHTML(m.name)+'"><span class="meme-template-image"><img src="'+escapeHTML(m.url)+'" alt="" loading="'+(i<4?'eager':'lazy')+'" referrerpolicy="no-referrer"><span class="meme-template-use">Usar fondo ↗</span></span><span class="meme-template-name">'+escapeHTML(m.name)+'</span></button>').join('')}
function selectMemeTemplate(url,name){if(!url)return;const image=new Image();image.crossOrigin='anonymous';image.referrerPolicy='no-referrer';image.onload=()=>{memeImage=image;drawMeme();document.querySelectorAll('.meme-template-card').forEach(b=>b.classList.toggle('selected',b.dataset.memeUrl===url));memeStatus('Fondo seleccionado: '+name+'. Podés arrastrar los dos textos en la imagen.');};image.onerror=()=>{memeImage=null;drawMeme();memeStatus('No se pudo cargar ese fondo. Probá con otra plantilla.');notify('No se pudo cargar la imagen elegida.')};image.src=url}
function drawMeme(){const c=document.querySelector('#meme-canvas');if(!c)return;const x=c.getContext('2d'),w=c.width,h=c.height;x.clearRect(0,0,w,h);if(memeImage&&memeImage.complete&&memeImage.naturalWidth){const scale=Math.max(w/memeImage.naturalWidth,h/memeImage.naturalHeight),iw=memeImage.naturalWidth*scale,ih=memeImage.naturalHeight*scale;x.drawImage(memeImage,(w-iw)/2,(h-ih)/2,iw,ih);x.fillStyle='rgba(0,0,0,.12)';x.fillRect(0,0,w,h)}else{x.fillStyle=memeColors[memeBg%memeColors.length];x.fillRect(0,0,w,h);x.fillStyle='#ffffff30';for(let i=0;i<8;i++){x.beginPath();x.arc((i*113+45)%w,(i*173+30)%h,28+(i%3)*12,0,Math.PI*2);x.fill()}x.fillStyle='#22251e';x.fillRect(30,30,w-60,h-60);x.fillStyle=memeColors[memeBg%memeColors.length];x.fillRect(42,42,w-84,h-84)}const size=Number(document.querySelector('#meme-size')?.value||42);x.font='900 '+size+'px "DM Sans", sans-serif';x.textAlign='center';x.textBaseline='middle';x.lineJoin='round';x.strokeStyle='#20211e';x.lineWidth=Math.max(3,size*.11);x.fillStyle=document.querySelector('#meme-color')?.value||'#ffffff';[[document.querySelector('#meme-top')?.value||'',memeTopPos],[document.querySelector('#meme-bottom')?.value||'',memeBottomPos]].forEach(([value,pos])=>{const words=value.toUpperCase().split(/\s+/);let lines=[],line='';for(const word of words){const next=line?line+' '+word:word;if(x.measureText(next).width>w-70&&line){lines.push(line);line=word}else line=next}if(line)lines.push(line);lines=lines.slice(0,4);const gap=size+5,startY=pos.y*h-(lines.length-1)*gap/2;lines.forEach((l,i)=>{x.strokeText(l,pos.x*w,startY+i*gap);x.fillText(l,pos.x*w,startY+i*gap)})});x.fillStyle='rgba(0,0,0,.62)';x.font='500 12px "DM Mono", monospace';x.textBaseline='alphabetic';x.fillText('NEXO / MEME LAB',w/2,h-15)}
function setupMeme(){['meme-top','meme-bottom','meme-color','meme-size'].forEach(id=>document.querySelector('#'+id)?.addEventListener('input',()=>{const size=document.querySelector('#meme-size');const label=document.querySelector('#meme-size-label');if(size&&label)label.textContent=size.value+' px';drawMeme()}));const c=document.querySelector('#meme-canvas');if(c){c.style.touchAction='none';c.addEventListener('pointerdown',e=>{const r=c.getBoundingClientRect(),px=(e.clientX-r.left)/r.width,py=(e.clientY-r.top)/r.height;const topD=Math.hypot((px-memeTopPos.x)*1.3,py-memeTopPos.y),bottomD=Math.hypot((px-memeBottomPos.x)*1.3,py-memeBottomPos.y);if(Math.min(topD,bottomD)>.22){memeDrag=null;return}memeDrag=topD<bottomD?'top':'bottom';c.setPointerCapture(e.pointerId);c.classList.add('is-dragging')});c.addEventListener('pointermove',e=>{if(!memeDrag)return;const r=c.getBoundingClientRect(),pos={x:Math.max(.08,Math.min(.92,(e.clientX-r.left)/r.width)),y:Math.max(.06,Math.min(.94,(e.clientY-r.top)/r.height))};if(memeDrag==='top')memeTopPos=pos;else memeBottomPos=pos;drawMeme()});const stop=()=>{memeDrag=null;c.classList.remove('is-dragging')};c.addEventListener('pointerup',stop);c.addEventListener('pointercancel',stop)}const form=document.querySelector('#meme-search-form');form?.addEventListener('submit',e=>{e.preventDefault();memeSearchTerm=document.querySelector('#meme-search')?.value.trim()||'';renderMemeResults()});document.querySelectorAll('[data-meme-query]').forEach(b=>b.addEventListener('click',()=>{const input=document.querySelector('#meme-search');if(input)input.value=b.dataset.memeQuery;memeSearchTerm=b.dataset.memeQuery;renderMemeResults()}));drawMeme();loadMemeTemplates()}
function surpriseMeme(){const pair=memeJokes[Math.floor(Math.random()*memeJokes.length)];const top=document.querySelector('#meme-top'),bottom=document.querySelector('#meme-bottom');if(top)top.value=pair[0];if(bottom)bottom.value=pair[1];memeTopPos={x:.5,y:.15};memeBottomPos={x:.5,y:.86};const pool=memeTemplates.length?memeTemplates.filter(m=>m.url):[];if(pool.length){const current=memeImage?.src;const options=pool.filter(m=>m.url!==current);const choice=options[Math.floor(Math.random()*Math.max(1,options.length))]||pool[0];selectMemeTemplate(choice.url,choice.name)}else{memeBg++;memeImage=null;drawMeme();loadMemeTemplates()}memeStatus('¡Sorpresa! Texto nuevo y fondo aleatorio. Podés editarlo todo.');notify('¡Meme sorpresa listo!')}
const ideas=['Un pingüino que abre una consultora de verano.','Un botón que solo funciona cuando dejás de mirarlo.','Mi talento oculto es posponer cosas con creatividad.','Un museo dedicado a los errores que salieron bien.','Una app para encontrar dónde dejaste la paciencia.','Un dragón que tiene miedo a las velas de cumpleaños.','Un lunes que se cree viernes.','Una tostadora que da consejos de vida.'];
function renderDiscover(){viewRoot.innerHTML=`<section class="page-content"><div class="content-heading"><div><p class="eyebrow">MUNDO 02 / CURIOSIDAD ACTIVA</p><h2>El mundo es más raro<br>de lo que parece.</h2><p>Una colección local de datos con enlaces para comprobarlos. Leé, guardá lo que te interese y seguí tirando del hilo.</p></div><button class="btn btn-dark" data-action="surprise-discovery">Sorprendeme ↗</button></div><div class="tool-panel"><div class="form-grid"><label class="field">Buscar curiosidades<input id="discovery-search" placeholder="Planetas, animales, ciencia..."></label><label class="field">Categoría<select id="discovery-category"><option value="">Todas las categorías</option>${[...new Set(discoveries.map(d=>d.category))].map(c=>`<option>${c}</option>`).join('')}</select></label></div><div class="button-row"><button class="pill-button active" data-discovery-filter="all">Todas</button><button class="pill-button" data-discovery-filter="saved">Mis favoritos</button><button class="pill-button" data-discovery-filter="new">No leídas</button></div><div class="item-list" id="discovery-list" style="margin-top:18px"></div><p class="muted" style="margin:18px 0 0;line-height:1.7">Nota: colección local inicial. Los enlaces conducen a instituciones y recursos de referencia; verificá los detalles en la fuente original.</p></div></section>`;document.querySelector('#discovery-search').addEventListener('input',renderDiscoveryList);document.querySelector('#discovery-category').addEventListener('change',renderDiscoveryList);document.querySelectorAll('[data-discovery-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-discovery-filter]').forEach(x=>x.classList.toggle('active',x===b));renderDiscoveryList()}));renderDiscoveryList()}
function renderDiscoveryList(){const root=document.querySelector('#discovery-list');if(!root)return;const q=(document.querySelector('#discovery-search')?.value||'').toLowerCase(),cat=document.querySelector('#discovery-category')?.value||'',filter=document.querySelector('[data-discovery-filter].active')?.dataset.discoveryFilter||'all';const list=discoveries.filter(d=>(!q||(d.title+' '+d.text+' '+d.category).toLowerCase().includes(q))&&(!cat||d.category===cat)&&(filter!=='saved'||state.favorites.includes(d.id))&&(filter!=='new'||!state.seen.includes(d.id)));root.innerHTML=list.length?list.map(d=>`<article class="item-row"><div class="item-main"><small>${escapeHTML(d.category.toUpperCase())} · ${state.seen.includes(d.id)?'YA VISTA':'POR DESCUBRIR'}</small><strong style="margin-top:5px">${escapeHTML(d.title)}</strong><p style="font-size:12px;line-height:1.65;margin:8px 0">${escapeHTML(d.text)}</p><small>Fuente: ${escapeHTML(d.source)} · <a href="${d.url}" target="_blank" rel="noopener noreferrer">Comprobar fuente ↗</a></small></div><button data-favorite="${d.id}" aria-label="Guardar favorito">${state.favorites.includes(d.id)?'★':'☆'}</button></article>`).join(''):'<div class="empty-state">No encontramos resultados con esos filtros.</div>';root.querySelectorAll('[data-favorite]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.favorite;state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();renderDiscoveryList();updateStats();notify('Favoritos actualizados')}));root.querySelectorAll('article').forEach((el,i)=>el.addEventListener('click',e=>{if(e.target.closest('button,a'))return;const d=list[i];if(d&&!state.seen.includes(d.id)){state.seen.push(d.id);save();el.querySelector('small').textContent=d.category.toUpperCase()+' · YA VISTA'}}))}

function loadReflexScores(){try{const list=JSON.parse(localStorage.getItem(REFLEX_STORAGE_KEY)||'[]');return Array.isArray(list)?list.filter(n=>Number.isFinite(n)&&n>0).sort((a,b)=>a-b).slice(0,3):[]}catch{return []}}
function saveReflexScores(){try{localStorage.setItem(REFLEX_STORAGE_KEY,JSON.stringify(reflexTimes))}catch{notify('No se pudo guardar el récord en este navegador.')}}
function renderReflexScores(){const list=document.querySelector('#reflex-scores');if(!list)return;list.innerHTML=reflexTimes.length?reflexTimes.map((time,index)=>'<li class="reflex-score-row"><span class="reflex-rank">'+['01','02','03'][index]+'</span><strong>'+time+'</strong><span>ms</span>'+(index===0?'<span class="reflex-crown">★</span>':'')+'</li>').join(''):'<li class="reflex-empty">Todavía no hay marcas. ¡Hacé la primera!</li>'}
function setReflexStatus(phase){const target=document.querySelector('#reflex-target'),word=document.querySelector('#reflex-target-word'),status=document.querySelector('#reflex-status'),message=document.querySelector('#reflex-message'),start=document.querySelector('#reflex-start'),again=document.querySelector('#reflex-again');if(!target)return;reflexPhase=phase;target.classList.remove('reflex-target-idle','reflex-target-waiting','reflex-target-go','reflex-target-early','reflex-target-result');target.classList.add(({idle:'reflex-target-idle',waiting:'reflex-target-waiting',go:'reflex-target-go',early:'reflex-target-early',result:'reflex-target-result'})[phase]||'reflex-target-idle');target.disabled=phase==='idle'||phase==='result';target.setAttribute('aria-label',phase==='go'?'¡Verde! Tocá ahora':phase==='waiting'?'Esperá a que el círculo se ponga verde':'Objetivo de reflejos');if(word)word.textContent=({idle:'LISTO',waiting:'ESPERÁ',go:'¡YA!',early:'¡UPS!',result:'FIN'})[phase]||'LISTO';if(status)status.textContent=({idle:'PREPARADO',waiting:'ESPERANDO SEÑAL',go:'¡AHORA!',early:'SALIDA EN FALSO',result:'RONDA TERMINADA'})[phase]||'PREPARADO';if(start)start.hidden=phase==='waiting'||phase==='go';if(again)again.hidden=phase!=='result'&&phase!=='early';if(phase==='idle'&&message)message.textContent='Presioná empezar y esperá la señal verde.'}
function stopReflexTimers(){if(reflexTimeout)clearTimeout(reflexTimeout);if(reflexTimer)clearTimeout(reflexTimer);reflexTimeout=reflexTimer=null}
function startReflexRound(){if(!document.querySelector('#reflex-game'))return;stopReflexTimers();const time=document.querySelector('#reflex-time'),message=document.querySelector('#reflex-message');if(time)time.innerHTML='—<small> ms</small>';if(message)message.textContent='No te adelantes. Tocá únicamente cuando aparezca el verde.';setReflexStatus('waiting');reflexTimer=setTimeout(()=>{if(reflexPhase!=='waiting')return;reflexStartedAt=performance.now();setReflexStatus('go');if(message)message.textContent='¡Ahora! Tocá el círculo.'},1500+Math.random()*4500)}
function burstReflexConfetti(){const host=document.querySelector('#reflex-card');if(!host)return;const layer=document.createElement('div');layer.className='reflex-confetti';layer.setAttribute('aria-hidden','true');for(let i=0;i<24;i++){const piece=document.createElement('i');piece.style.setProperty('--confetti-x',(Math.random()*240-120)+'px');piece.style.setProperty('--confetti-y',(-35-Math.random()*125)+'px');piece.style.setProperty('--confetti-rotate',(Math.random()*600-300)+'deg');piece.style.setProperty('--confetti-delay',(Math.random()*.2)+'s');layer.appendChild(piece)}host.appendChild(layer);setTimeout(()=>layer.remove(),1400)}
function handleReflexTap(){if(reflexPhase==='waiting'){stopReflexTimers();setReflexStatus('early');const time=document.querySelector('#reflex-time'),message=document.querySelector('#reflex-message');if(time)time.innerHTML='—<small> ms</small>';if(message)message.innerHTML='<span class="reflex-too-fast">¡Demasiado rápido!</span> Esperá a que el círculo se ponga verde.';const target=document.querySelector('#reflex-target');if(target){target.classList.add('reflex-shake');setTimeout(()=>target.classList.remove('reflex-shake'),350)}if(navigator.vibrate)try{navigator.vibrate(80)}catch{}return}if(reflexPhase!=='go')return;const elapsed=Math.max(0,Math.round(performance.now()-reflexStartedAt));stopReflexTimers();setReflexStatus('result');const time=document.querySelector('#reflex-time'),message=document.querySelector('#reflex-message');if(time)time.innerHTML=elapsed+'<small> ms</small>';const previous=reflexTimes.slice();reflexTimes=[...reflexTimes,elapsed].sort((a,b)=>a-b).slice(0,3);const isRecord=!previous.length||elapsed<previous[0];if(message)message.textContent=elapsed<220?'¡Reflejos rapidísimos!':elapsed<320?'¡Muy buena reacción!':'¡Bien jugado! Probá otra vez para mejorar.';if(isRecord){saveReflexScores();burstReflexConfetti();if(navigator.vibrate)try{navigator.vibrate([35,45,70])}catch{}if(message)message.textContent='¡Nuevo récord personal! '+elapsed+' ms. ¡Excelente reflejo!'}renderReflexScores()}
function setupReflexGame(){reflexTimes=loadReflexScores();renderReflexScores()}

function renderGames(){viewRoot.innerHTML=`<section class="page-content"><div class="content-heading"><div><p class="eyebrow">MUNDO 03 / JUEGO LIMPIO</p><h2>Probá lo que sabés.<br>Descubrí lo que falta.</h2><p>Partidas individuales, puntuación local y explicaciones para aprender jugando.</p></div></div><div class="world-grid" style="grid-template-columns:repeat(auto-fit,minmax(260px,1fr))"><article class="tool-panel"><p class="section-label">JUEGO 01 / TRIVIA</p><h3 style="font:800 25px Manrope">Mente curiosa</h3><p class="muted" style="line-height:1.7">Ocho preguntas, cuatro opciones y una explicación después de cada respuesta.</p><div class="stats-row"><div><strong>08</strong><span>preguntas</span></div><div><strong id="quiz-best">\${state.quizBest}</strong><span>mejor puntaje</span></div><div><strong>∞</strong><span>revancha</span></div></div><button class="btn btn-dark" data-action="start-quiz">Empezar trivia ↗</button><div id="quiz-area" style="margin-top:18px"></div></article><article class="tool-panel"><p class="section-label">JUEGO 02 / PALABRAS</p><h3 style="font:800 25px Manrope">La palabra escondida</h3><p class="muted" style="line-height:1.7">Descubrí una palabra con pistas. Cada intento cuenta; podés pedir una pista adicional.</p><div id="word-area"><div class="result-box">¿Te animás a resolverla?</div><button class="btn btn-outline" style="margin-top:13px" data-action="start-word">Jugar ahora ↗</button></div></article><article class="tool-panel reflex-card" id="reflex-card"><button class="reflex-expand-toggle" type="button" data-action="toggle-reflex" aria-expanded="false" aria-controls="reflex-game"><span><span class="section-label">JUEGO 03 / VELOCIDAD</span><strong>Reflejos Ninja</strong><small>¿Qué tan rápido reaccionás?</small></span><span class="reflex-expand-icon" aria-hidden="true">＋</span></button><div class="reflex-game" id="reflex-game" hidden><div class="reflex-game-head"><span class="reflex-status-pill" id="reflex-status">PREPARADO</span><span class="reflex-round">TOCÁ CUANDO SE PONGA VERDE</span></div><button type="button" class="reflex-target reflex-target-idle" id="reflex-target" data-action="reflex-target" aria-label="Objetivo de reflejos. Iniciá una ronda primero"><span class="reflex-target-core"></span><span class="reflex-target-word" id="reflex-target-word">LISTO</span></button><div class="reflex-result" aria-live="polite"><strong id="reflex-time">—<small> ms</small></strong><p id="reflex-message">Presioná empezar y esperá la señal verde.</p></div><div class="reflex-actions"><button class="btn btn-dark" id="reflex-start" type="button" data-action="reflex-start">Empezar ronda ↗</button><button class="btn btn-quiet" id="reflex-again" type="button" data-action="reflex-start" hidden>Otra vez</button></div><div class="reflex-leaderboard"><div class="reflex-board-heading"><div><p class="section-label">TU PODIO LOCAL</p><h4>Top 3 mejores tiempos</h4></div><span>MENOS MS = MEJOR</span></div><ol id="reflex-scores" class="reflex-scores"><li class="reflex-empty">Todavía no hay marcas. ¡Hacé la primera!</li></ol><p class="reflex-local-note">Récords guardados solo en este navegador.</p></div></div></article></div></section>`}
function startQuiz(){quiz={questions:[...quizQuestions].sort(()=>Math.random()-.5).slice(0,5),index:0,score:0,answered:false};renderQuizQuestion()}
function renderQuizQuestion(){const root=document.querySelector('#quiz-area');if(!root||!quiz)return;if(quiz.index>=quiz.questions.length){state.quizBest=Math.max(state.quizBest,quiz.score);state.points+=quiz.score*5;save();updateStats();root.innerHTML=`<div class="result-box"><p class="section-label">RONDA TERMINADA</p><h3 style="font:800 25px Manrope">${quiz.score} de ${quiz.questions.length}</h3><p>${quiz.score===5?'¡Impecable!':quiz.score>=3?'¡Buen trabajo!':'Cada pregunta suma experiencia.'} ${quiz.score*5} puntos ganados.</p><div class="progress-track"><div class="progress-fill" style="width:${quiz.score/quiz.questions.length*100}%"></div></div><button class="btn btn-dark" style="margin-top:16px" data-action="start-quiz">Jugar otra vez ↗</button></div>`;return}const q=quiz.questions[quiz.index];root.innerHTML=`<p class="section-label">PREGUNTA ${quiz.index+1} / ${quiz.questions.length} · PUNTOS ${quiz.score}</p><div class="progress-track"><div class="progress-fill" style="width:${quiz.index/quiz.questions.length*100}%"></div></div><h3 style="font:700 18px/1.45 Manrope;margin:18px 0 10px">${escapeHTML(q.q)}</h3><div>${q.options.map((o,i)=>`<button class="quiz-option" data-answer="${i}">${escapeHTML(o)}</button>`).join('')}</div><div id="quiz-feedback"></div>`;root.querySelectorAll('[data-answer]').forEach(b=>b.addEventListener('click',()=>{if(quiz.answered)return;quiz.answered=true;const correct=Number(b.dataset.answer)===q.correct;if(correct)quiz.score++;root.querySelectorAll('[data-answer]').forEach(btn=>{btn.disabled=true;if(Number(btn.dataset.answer)===q.correct)btn.classList.add('correct')});if(!correct)b.classList.add('wrong');document.querySelector('#quiz-feedback').innerHTML=`<div class="result-box" style="margin-top:13px"><strong>${correct?'¡Correcto!':'No era esa, y está bien.'}</strong><p style="font-size:12px;margin:7px 0 0">${escapeHTML(q.explain)}</p><button class="btn btn-dark" style="margin-top:12px" data-action="next-question">${quiz.index===quiz.questions.length-1?'Ver resultado':'Siguiente pregunta'} →</button></div>`;document.querySelector('[data-action="next-question"]').addEventListener('click',()=>{quiz.index++;quiz.answered=false;renderQuizQuestion()})}))}
const wordBank=[{word:'PLANETA',hint:'Un cuerpo celeste que orbita una estrella.',extra:'La Tierra es uno de ellos.'},{word:'BRUJULA',hint:'Ayuda a orientarse usando el campo magnético terrestre.',extra:'Su aguja señala aproximadamente el norte magnético.'},{word:'TECLADO',hint:'Lo usás para escribir en una computadora.',extra:'Puede ser mecánico o de membrana.'},{word:'BOSQUE',hint:'Ecosistema donde predominan los árboles.',extra:'Puede albergar una enorme biodiversidad.'}];
function startWord(){const item=wordBank[Math.floor(Math.random()*wordBank.length)];wordRound={item,tries:0,usedHint:false};renderWord()}
function renderWord(){const root=document.querySelector('#word-area');if(!root||!wordRound)return;root.innerHTML=`<p class="section-label">PISTA ${wordRound.usedHint?2:1} · INTENTOS ${wordRound.tries}</p><div class="result-box">${escapeHTML(wordRound.item.hint)}<p id="word-extra" style="margin:8px 0 0">${wordRound.usedHint?escapeHTML(wordRound.item.extra):''}</p></div><form id="word-form" style="margin-top:14px"><label class="field">Tu respuesta<input id="word-answer" autocomplete="off" maxlength="30" required placeholder="Escribí una palabra..."></label><div class="button-row"><button class="btn btn-dark">Probar respuesta ↗</button><button type="button" class="btn btn-quiet" id="word-hint">Otra pista</button></div></form><div id="word-feedback"></div>`;document.querySelector('#word-hint').addEventListener('click',()=>{wordRound.usedHint=true;renderWord()});document.querySelector('#word-form').addEventListener('submit',e=>{e.preventDefault();const val=document.querySelector('#word-answer').value.trim().normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase();wordRound.tries++;if(val===wordRound.item.word){const pts=Math.max(5,20-wordRound.tries*3-(wordRound.usedHint?5:0));state.points+=pts;state.wordBest=Math.max(state.wordBest,pts);save();updateStats();document.querySelector('#word-feedback').innerHTML=`<div class="result-box" style="margin-top:12px"><strong>¡La encontraste! +${pts} puntos</strong><p>La palabra era ${escapeHTML(wordRound.item.word)}.</p><button type="button" class="btn btn-dark" id="word-again">Otra palabra ↗</button></div>`;document.querySelector('#word-form').remove();document.querySelector('#word-again').addEventListener('click',startWord)}else{document.querySelector('#word-feedback').innerHTML=`<p style="font-size:12px;margin-top:12px">${wordRound.tries>=5?'Pista: la palabra tiene '+wordRound.item.word.length+' letras.':'Todavía no. Probá otra vez, ¡vas bien!'}</p>`}})}
function renderProgress(){const total=state.tasks.length,done=state.tasks.filter(t=>t.done).length;viewRoot.innerHTML=`<section class="page-content"><div class="content-heading"><div><p class="eyebrow">MUNDO 04 / TU ESPACIO</p><h2>Avanzar también es<br>ir a tu ritmo.</h2><p>Una lista clara para sacar cosas de la cabeza y llevarlas al día. Sin rachas obligatorias ni culpa por cambiar de plan.</p></div></div><div class="world-grid" style="grid-template-columns:repeat(auto-fit,minmax(280px,1fr));align-items:start"><article class="tool-panel"><p class="section-label">01 / LISTA DE TAREAS</p><form id="task-form"><label class="field">¿Qué querés hacer?<input id="task-title" maxlength="120" required placeholder="Ej. Leer un capítulo, ordenar el escritorio..."></label><div class="form-grid" style="margin-top:12px"><label class="field">Fecha (opcional)<input id="task-date" type="date"></label><label class="field">Tipo<select id="task-type"><option>Personal</option><option>Estudio</option><option>Proyecto</option><option>Descanso</option></select></label></div><button class="btn btn-dark" style="margin-top:13px">Agregar tarea +</button></form><div class="button-row"><button class="pill-button active" data-task-filter="all">Todas</button><button class="pill-button" data-task-filter="open">Pendientes</button><button class="pill-button" data-task-filter="done">Completadas</button></div><div id="task-list" class="item-list" style="margin-top:14px"></div><div style="margin-top:17px"><div style="display:flex;justify-content:space-between;font-size:11px;margin-bottom:8px"><span>Tu avance</span><strong>${done}/${total}</strong></div><div class="progress-track"><div class="progress-fill" style="width:${total?done/total*100:0}%"></div></div></div></article><article class="tool-panel"><p class="section-label">02 / ENFOQUE FLEXIBLE</p><h3 style="font:800 24px Manrope">Un rato para vos.</h3><p class="muted" style="line-height:1.7">Elegí un tiempo, hacé una cosa a la vez y descansá cuando lo necesites.</p><div style="text-align:center;padding:24px 0"><div id="timer-display" style="font:800 clamp(48px,7vw,70px) Manrope;letter-spacing:-3px;font-variant-numeric:tabular-nums">25:00</div><p id="timer-status" class="muted">LISTO CUANDO VOS ESTÉS</p></div><label class="field">Duración<select id="timer-duration"><option value="15">15 minutos</option><option value="25" selected>25 minutos</option><option value="45">45 minutos</option><option value="5">5 minutos de prueba</option></select></label><div class="button-row"><button class="btn btn-dark" id="timer-start">Empezar</button><button class="btn btn-quiet" id="timer-reset">Reiniciar</button></div><hr style="border:0;border-top:1px solid var(--line);margin:24px 0"><p class="section-label">03 / TU ACTIVIDAD</p><div class="stats-row"><div><strong>${done}</strong><span>tareas listas</span></div><div><strong>${state.favorites.length}</strong><span>favoritos</span></div><div><strong>${state.points}</strong><span>puntos</span></div></div><button class="btn btn-outline btn-full" data-action="export-data">Exportar copia JSON ↗</button><label class="field" style="margin-top:14px">Restaurar una copia<input type="file" id="import-file" accept="application/json,.json"></label><p class="muted" style="line-height:1.6;margin-top:9px">Tus datos se guardan en este navegador. Exportá una copia si querés conservarlos o moverlos a otro equipo.</p></article></div></section>`;wireTasks();wireTimer();wireBackup()}
let taskFilter='all';
function wireTasks(){document.querySelector('#task-form').addEventListener('submit',e=>{e.preventDefault();const title=document.querySelector('#task-title').value.trim();if(!title)return;state.tasks.unshift({id:crypto.randomUUID?crypto.randomUUID():String(Date.now()),title,date:document.querySelector('#task-date').value,type:document.querySelector('#task-type').value,done:false,created:Date.now()});save();renderProgress();notify('Tarea agregada')});document.querySelectorAll('[data-task-filter]').forEach(b=>b.addEventListener('click',()=>{taskFilter=b.dataset.taskFilter;document.querySelectorAll('[data-task-filter]').forEach(x=>x.classList.toggle('active',x===b));renderTaskList()}));renderTaskList()}
function renderTaskList(){const root=document.querySelector('#task-list');if(!root)return;const tasks=state.tasks.filter(t=>taskFilter==='all'||(taskFilter==='done'?t.done:!t.done));root.innerHTML=tasks.length?tasks.map(t=>`<div class="item-row"><input type="checkbox" class="check" data-task-check="${escapeHTML(t.id)}" ${t.done?'checked':''} aria-label="Completar tarea"><div class="item-main"><strong style="${t.done?'text-decoration:line-through;opacity:.6':''}">${escapeHTML(t.title)}</strong><small>${escapeHTML(t.type)}${t.date?' · '+escapeHTML(t.date):''}</small></div><button data-task-edit="${escapeHTML(t.id)}">Editar</button><button data-task-delete="${escapeHTML(t.id)}" aria-label="Eliminar tarea">×</button></div>`).join(''):'<div class="empty-state">Todavía no hay tareas en esta vista. Podés empezar con algo pequeño.</div>';root.querySelectorAll('[data-task-check]').forEach(el=>el.addEventListener('change',()=>{const t=state.tasks.find(x=>x.id===el.dataset.taskCheck);if(t&&!t.done&&el.checked)state.points+=3;if(t)t.done=el.checked;save();renderProgress();notify(el.checked?'Tarea completada. ¡Bien ahí!':'Tarea reabierta')}));root.querySelectorAll('[data-task-delete]').forEach(el=>el.addEventListener('click',()=>{state.tasks=state.tasks.filter(t=>t.id!==el.dataset.taskDelete);save();renderProgress();notify('Tarea eliminada')}));root.querySelectorAll('[data-task-edit]').forEach(el=>el.addEventListener('click',()=>{const t=state.tasks.find(x=>x.id===el.dataset.taskEdit);if(!t)return;const val=prompt('Editar tarea:',t.title);if(val===null)return;if(!val.trim()){notify('El título no puede quedar vacío');return}t.title=val.trim().slice(0,120);save();renderTaskList();notify('Tarea actualizada')}))}
let timerInterval=null,timerRemaining=1500;
function wireTimer(){const display=document.querySelector('#timer-display'),status=document.querySelector('#timer-status'),duration=document.querySelector('#timer-duration');if(!display)return;timerRemaining=Number(duration.value)*60;const paint=()=>display.textContent=String(Math.floor(timerRemaining/60)).padStart(2,'0')+':'+String(timerRemaining%60).padStart(2,'0');paint();duration.addEventListener('change',()=>{stopTimer();timerRemaining=Number(duration.value)*60;paint();status.textContent='LISTO CUANDO VOS ESTÉS'});document.querySelector('#timer-start').addEventListener('click',()=>{if(timerInterval){stopTimer();status.textContent='PAUSA CUANDO LA NECESITES';return}status.textContent='MOMENTO DE ENFOQUE';document.querySelector('#timer-start').textContent='Pausar';timerInterval=setInterval(()=>{timerRemaining--;paint();if(timerRemaining<=0){stopTimer();status.textContent='TIEMPO COMPLETADO. ¡BIEN HECHO!';state.points+=5;save();updateStats();notify('Terminaste tu sesión de enfoque. ¡Tomate un descanso!')}},1000)});document.querySelector('#timer-reset').addEventListener('click',()=>{stopTimer();timerRemaining=Number(duration.value)*60;paint();status.textContent='REINICIADO';document.querySelector('#timer-start').textContent='Empezar'})}
function stopTimer(){if(timerInterval)clearInterval(timerInterval);timerInterval=null;const b=document.querySelector('#timer-start');if(b)b.textContent='Empezar'}
function wireBackup(){document.querySelector('[data-action="export-data"]')?.addEventListener('click',exportData);document.querySelector('#import-file')?.addEventListener('change',importData)}
function exportData(){const blob=new Blob([JSON.stringify({version:1,exportedAt:new Date().toISOString(),state},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='nexo-copia-'+new Date().toISOString().slice(0,10)+'.json';a.click();URL.revokeObjectURL(a.href);notify('Copia preparada para descargar')}
function importData(e){const file=e.target.files?.[0];if(!file)return;if(file.size>2_000_000){notify('El archivo es demasiado grande');return}const reader=new FileReader();reader.onload=()=>{try{const parsed=JSON.parse(reader.result),s=parsed.state||parsed;if(!s||!Array.isArray(s.tasks)||!Array.isArray(s.favorites))throw Error('formato');state={...defaultState,...s,tasks:s.tasks.filter(t=>t&&typeof t.title==='string').slice(0,1000),favorites:s.favorites.filter(x=>typeof x==='string').slice(0,1000),seen:Array.isArray(s.seen)?s.seen.filter(x=>typeof x==='string').slice(0,1000):[]};save();setView(currentView);notify('Copia restaurada')}catch{notify('La copia no tiene un formato válido')}e.target.value=''};reader.readAsText(file)}
function surprise(){const views=['crear','descubrir','jugar','progreso','agenda','bienestar','aprender'];setView(views[Math.floor(Math.random()*views.length)])}
function generateIdea(){const result=document.querySelector('#idea-result');if(result)result.textContent=ideas[Math.floor(Math.random()*ideas.length)]}
function generateCharacter(){const names=['Lola Tornillo','Capitán Mandarina','Rita Cometa','Don Bigote','Pixel Fernández','Mora Galáctica'];const powers=['puede encontrar cosas perdidas, excepto sus llaves','habla con electrodomésticos tímidos','convierte problemas pequeños en misiones épicas','recuerda todos los sueños ajenos','puede detener el tiempo durante dos segundos'];const flaws=['pero le teme a las palomas','pero nunca entiende los mapas','pero se distrae con cualquier ruido','pero siempre llega cinco minutos temprano','pero no sabe guardar secretos'];const el=document.querySelector('#character-result');if(el)el.textContent=names[Math.floor(Math.random()*names.length)]+' tiene el poder de '+powers[Math.floor(Math.random()*powers.length)+0]+', '+flaws[Math.floor(Math.random()*flaws.length)]+'.'}
function surpriseDiscovery(){const d=discoveries[Math.floor(Math.random()*discoveries.length)];state.seen=[...new Set([...state.seen,d.id])];save();renderDiscoveryList();notify('Descubrimiento: '+d.title)}
function resetAll(){try{localStorage.removeItem(WELLBEING_HOME_KEY)}catch{}state={...defaultState,tasks:[],favorites:[],seen:[],points:0,quizBest:0,wordBest:0,created:0,notes:'',goals:[],focusSessions:0,reflection:{good:'',learn:'',next:''},wellnessLog:{},learningDone:[]};save();setTheme();setView('inicio');notify('Datos locales borrados')}
document.addEventListener('submit',e=>{if(e.target.id==='meme-search-form'){e.preventDefault();memeSearchTerm=document.querySelector('#meme-search')?.value.trim()||'';renderMemeResults()}if(e.target.id==='wellness-form'){e.preventDefault();saveWellness()}if(e.target.id==='goal-form'){e.preventDefault();const input=document.querySelector('#goal-input'),text=input.value.trim();if(!text)return;if((state.goals||[]).length>=3){notify('Probá con un máximo de tres prioridades.');return}state.goals=[...(state.goals||[]),{text,done:false}];save();renderGoals();input.value='';notify('Prioridad agregada.')}});
document.addEventListener('change',e=>{if(e.target.closest('#wellness-form')){saveWellness();return}if(e.target.matches('[data-learning-module]')){const id=e.target.dataset.learningModule;state.learningDone=Array.isArray(state.learningDone)?state.learningDone:[];if(e.target.checked&&!state.learningDone.includes(id)){state.learningDone.push(id);state.points+=2;notify('Módulo completado: +2 puntos')}else if(!e.target.checked)state.learningDone=state.learningDone.filter(x=>x!==id);save();renderLearning();return}if(e.target.matches('[data-goal-toggle]')){const i=Number(e.target.dataset.goalToggle);if(state.goals[i]){state.goals[i].done=e.target.checked;if(e.target.checked)state.points+=3;save();renderGoals()}}});
document.addEventListener('click',e=>{const memeCard=e.target.closest('[data-meme-url]');if(memeCard){selectMemeTemplate(memeCard.dataset.memeUrl,memeCard.dataset.memeName||'Plantilla');return}const memeQuery=e.target.closest('[data-meme-query]');if(memeQuery){const input=document.querySelector('#meme-search');if(input)input.value=memeQuery.dataset.memeQuery;memeSearchTerm=memeQuery.dataset.memeQuery;renderMemeResults();return}const healthStep=e.target.closest('[data-health-step]');if(healthStep){adjustWellness(healthStep);return}const del=e.target.closest('[data-goal-delete]');if(del){state.goals.splice(Number(del.dataset.goalDelete),1);save();renderGoals();return}const preset=e.target.closest('[data-focus-min]');if(preset){stopFocus();focusTotal=focusRemaining=Number(preset.dataset.focusMin)*60;document.querySelectorAll('[data-focus-min]').forEach(b=>b.classList.toggle('active',b===preset));const l=document.querySelector('#focus-label');if(l)l.textContent='MINUTOS PARA VOS';paintFocus();return}const nav=e.target.closest('[data-view]');if(nav){setView(nav.dataset.view);return}const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;switch(action){case'surprise':surprise();break;case'new-prompt':document.querySelector('#daily-text').textContent=prompts[Math.floor(Math.random()*prompts.length)];break;case'reset':document.querySelector('#confirm-dialog').showModal();break;case'generate-idea':generateIdea();break;case'copy-idea':navigator.clipboard?.writeText(document.querySelector('#idea-result')?.textContent||'').then(()=>notify('Texto copiado')).catch(()=>notify('Seleccioná y copiá el texto manualmente'));break;case'generate-character':generateCharacter();break;case'download-meme':{const c=document.querySelector('#meme-canvas');if(c){try{const a=document.createElement('a');a.download='nexo-meme.png';a.href=c.toDataURL('image/png');a.click();state.created++;save();notify('Tu meme se descargó como PNG')}catch(err){notify('Ese fondo no permite exportación directa. Elegí otra plantilla o usá el fondo gráfico.')}}break}case'random-meme':if(memeTemplates.length){const pool=memeTemplates.filter(m=>m.url!==memeImage?.src);const choice=pool[Math.floor(Math.random()*Math.max(1,pool.length))]||memeTemplates[0];selectMemeTemplate(choice.url,choice.name)}else{memeBg++;memeImage=null;drawMeme();loadMemeTemplates()}break;case'surprise-meme':surpriseMeme();break;case'surprise-discovery':surpriseDiscovery();break;case'start-quiz':startQuiz();break;case'start-word':startWord();break;case'toggle-reflex':{const panel=document.querySelector('#reflex-game'),toggle=document.querySelector('[data-action="toggle-reflex"]');if(panel&&toggle){const opening=panel.hidden;panel.hidden=!opening;toggle.setAttribute('aria-expanded',String(opening));toggle.querySelector('.reflex-expand-icon').textContent=opening?'−':'＋';if(opening)setupReflexGame();else stopReflexTimers()}break}case'reflex-start':startReflexRound();break;case'reflex-target':handleReflexTap();break;case'export-data':exportData();break;case'focus-start':startFocus();break;case'focus-pause':stopFocus();notify('Temporizador en pausa.');break;case'focus-reset':setupFocus();break;case'save-notes':saveNotes();break;case'save-reflection':saveReflection();break;case'wellness-step':adjustWellness(e.target.closest('[data-health-step]'));break;case'wellness-save':saveWellness();break;case'wellness-reset':resetWellnessToday();break;case'learning-reset':resetLearning();break}});
document.querySelector('#theme-toggle').addEventListener('click',()=>{state.theme=state.theme==='dark'?'light':'dark';save();setTheme()});document.querySelector('#mobile-theme').addEventListener('click',()=>{state.theme=state.theme==='dark'?'light':'dark';save();setTheme()});document.querySelector('#confirm-reset').addEventListener('click',e=>{e.preventDefault();document.querySelector('#confirm-dialog').close();resetAll()});document.querySelector('#profile-button').addEventListener('click',()=>notify('Modo local: no necesitás una cuenta para usar NEXO.'));
document.querySelector('#global-search').addEventListener('keydown',e=>{if(e.key==='Enter'){const q=e.target.value.trim().toLowerCase();if(!q)return;const d=discoveries.find(d=>(d.title+' '+d.text+' '+d.category).toLowerCase().includes(q));if(d){setView('descubrir');setTimeout(()=>{document.querySelector('#discovery-search').value=e.target.value;renderDiscoveryList()},0)}else if(['meme','crear','idea','frase'].some(k=>q.includes(k)))setView('crear');else if(['juego','trivia','palabra'].some(k=>q.includes(k)))setView('jugar');else if(['tarea','progreso','enfoque','agenda','organizar'].some(k=>q.includes(k)))setView('progreso');else if(['salud','bienestar','movimiento','descanso','agua','sueño'].some(k=>q.includes(k)))setView('bienestar');else if(['aprender','estudiar','html','css','javascript','ciencia'].some(k=>q.includes(k)))setView('aprender');else{setView('descubrir');setTimeout(()=>{const inp=document.querySelector('#discovery-search');if(inp){inp.value=e.target.value;renderDiscoveryList()}},0)}}});
function initializeHome(){const html=document.querySelector('#app-view').innerHTML;viewRoot.innerHTML=html;document.querySelector('#daily-text').textContent=prompts[Math.floor(Math.random()*prompts.length)];updateStats();setTheme()}
initializeHome();
